CREATE TABLE weather_alerts(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_id` bigint  NULL COMMENT 'NULL for region-wide alerts',`state` varchar(255)  NOT NULL,`district` varchar(255)  NULL,`alert_type` varchar(255)  NOT NULL COMMENT 'extreme_heat, heavy_rain, storm, hail, drought',`severity` varchar(255)  NOT NULL COMMENT 'low, medium, high, critical',`message` text  NOT NULL,`recommendation` text  NULL COMMENT 'Action recommendations',`valid_from` timestamp  NOT NULL,`valid_until` timestamp  NOT NULL,`is_active` TINYINT(1)  DEFAULT 1)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;